  "code": "def encode(message):
    """
    Construct a function that takes a message and encodes it by
    changing the case of each letter and replacing each vowel with
    the letter that is two places ahead in the alphabet.
    The function expects the input to be a string of letters only.

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = {'a', 'e', 'i', 'o', 'u'}
    encoded_message = []
    for char in message:
        if char.isalpha():
            # Change the case of each letter
            if char.islower():
                new_char = char.upper()
            else:
                new_char = char.lower()

            # Replace each vowel with the letter that is two places ahead in the alphabet
            if new_char.lower() in vowels:
                new_char = chr(ord(new_char) + 2)
            encoded_message.append(new_char)
        else:
            encoded_message.append(char)
    return ''.join(encoded_message)",
